<?php require_once 'app.php';require_login();header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório</title><link href="estilo.css" rel="stylesheet"></head><body onload="window.print()"><div class="container py-4"><h1>Relatório financeiro</h1><p>Gerado em <?=date('d/m/Y H:i')?> por <?=e(user()['nome'])?></p><?php $s=db()->prepare('SELECT * FROM transacoes WHERE usuario_id=? ORDER BY data_lancamento DESC');$s->execute([user()['id']]);?><table class="table"><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Valor</th></tr><?php foreach($s as $r):?><tr><td><?=e($r['data_lancamento'])?></td><td><?=e($r['descricao'])?></td><td><?=e($r['tipo'])?></td><td><?=money($r['valor'])?></td></tr><?php endforeach;?></table></div></body></html>